pieces=[]
for r in range(6):
 for c in range(6):
  sq={(r+i,c+j) for i in range(2) for j in range(2)}
  if sq<=S: pieces.append(('sq',None,sq))
  for miss in [(i,j) for i in range(2) for j in range(2)]:
   shape={(r+i,c+j) for i in range(2) for j in range(2) if (i,j)!=miss}
   if shape<=S: pieces.append(('L',miss,shape))
sols=[]
def search(rem, chosen):
 if not rem:
  sols.append(chosen); return
 cell=min(rem)
 for p in pieces:
  if cell in p[2] and p[2]<=rem:
   search(rem-p[2],chosen+[p])
search(S,[])
len(sols), [[(p[0],p[1],sorted(p[2])) for p in sol] for sol in sols[:5]]
